export const getHandleUssdUrl = () => {




  return `/api/ussd`
}

/**
 * @summary Africa's Talking USSD webhook
 */
export const handleUssd = async (ussdRequest: UssdRequest, options?: RequestInit): Promise<string> => {
    const formUrlEncoded = new URLSearchParams();
formUrlEncoded.append(`sessionId`, ussdRequest.sessionId);
formUrlEncoded.append(`phoneNumber`, ussdRequest.phoneNumber);
formUrlEncoded.append(`text`, ussdRequest.text);
if(ussdRequest.networkCode !== undefined) {
 formUrlEncoded.append(`networkCode`, ussdRequest.networkCode);
 }
if(ussdRequest.serviceCode !== undefined) {
 formUrlEncoded.append(`serviceCode`, ussdRequest.serviceCode);
 }

  return customFetch<string>(getHandleUssdUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', ...options?.headers },
    body:
      formUrlEncoded,
  }
);}




